"""The ``pennywise`` command-line interface."""

import argparse
import csv
import datetime
import io
import json
import os
import sys
from typing import List, Optional

from .core import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_line,
)

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _ReadError(Exception):
    pass


def _date_arg(text: str) -> datetime.date:
    try:
        return datetime.date.fromisoformat(text) if len(text) == 10 else _bad_date(text)
    except ValueError:
        _bad_date(text)


def _bad_date(text: str):
    raise argparse.ArgumentTypeError(f"invalid date {text!r} (expected an existing date as YYYY-MM-DD)")


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def ledger(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or '-' for standard input")

    def json_flag(p):
        p.add_argument("--json", action="store_true", help="print JSON instead of text")

    p = sub.add_parser("balance", help="print the total of all amounts")
    ledger(p)
    json_flag(p)

    p = sub.add_parser("summary", help="print totals per category or month")
    ledger(p)
    p.add_argument("--by", choices=["category", "month"], default="category")
    json_flag(p)

    p = sub.add_parser("list", help="print matching entries, oldest first")
    ledger(p)
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    json_flag(p)

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    ledger(p)
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _read_text(path: str) -> str:
    try:
        if path == "-":
            data = sys.stdin.buffer.read()
        else:
            with open(path, "rb") as f:
                data = f.read()
        return data.decode("utf-8-sig")
    except OSError as exc:
        raise _ReadError(f"cannot read {path}: {exc.strerror or exc}") from None
    except UnicodeDecodeError:
        raise _ReadError(f"cannot read {path}: not valid UTF-8 text") from None


def _sorted_by_date(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same-day keeps file order


def _entry_json(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _cmd_balance(args, entries) -> str:
    total = format_amount(balance(entries))
    if args.json:
        return json.dumps({"balance": total})
    return total


def _cmd_summary(args, entries) -> str:
    groups = by_month(entries) if args.by == "month" else by_category(entries)
    if args.json:
        return json.dumps({k: format_amount(v) for k, v in groups.items()})
    return "\n".join(f"{k}  {format_amount(v)}" for k, v in groups.items())


def _cmd_list(args, entries) -> str:
    chosen = _sorted_by_date(
        filter_entries(entries, category=args.category, since=args.since, until=args.until)
    )
    if args.json:
        return json.dumps([_entry_json(e) for e in chosen])
    return "\n".join(format_entry(e) for e in chosen)


def _cmd_export(args, entries) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted_by_date(entries):
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buf.getvalue().rstrip("\n")


def _cmd_add(args) -> int:
    fields = [args.date, args.category, args.amount]
    for name, value in zip(("date", "category", "amount"), fields):
        if not value or any(c in value for c in " \t\r\n"):
            print(f"pennywise: invalid entry: {name} {value!r} must be a single word", file=sys.stderr)
            return EXIT_LEDGER
    if "\n" in args.note or "\r" in args.note:
        print("pennywise: invalid entry: note must not contain line breaks", file=sys.stderr)
        return EXIT_LEDGER
    raw = " ".join(fields + ([args.note] if args.note.strip() else []))
    try:
        entry = parse_line(raw, 1)
    except ParseError as exc:
        print(f"pennywise: invalid entry {raw!r}: {exc.reason}", file=sys.stderr)
        return EXIT_LEDGER
    line = format_entry(entry)

    path = args.file
    try:
        prefix = ""
        if os.path.exists(path):
            with open(path, "rb") as f:
                f.seek(0, os.SEEK_END)
                if f.tell() > 0:
                    f.seek(-1, os.SEEK_END)
                    if f.read(1) != b"\n":
                        prefix = "\n"
        with open(path, "a", encoding="utf-8", newline="") as f:
            f.write(prefix + line + "\n")
    except OSError as exc:
        print(f"pennywise: cannot write {path}: {exc.strerror or exc}", file=sys.stderr)
        return EXIT_USAGE
    print(line)
    return EXIT_OK


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:  # argparse: usage errors exit 2, --help exits 0
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE

    if args.command == "add":
        return _cmd_add(args)

    try:
        text = _read_text(args.file)
    except _ReadError as exc:
        print(f"pennywise: {exc}", file=sys.stderr)
        return EXIT_USAGE
    try:
        entries = parse(text)
    except ParseError as exc:
        name = "<stdin>" if args.file == "-" else args.file
        print(f"pennywise: {name}: {exc}", file=sys.stderr)
        return EXIT_LEDGER

    output = _COMMANDS[args.command](args, entries)
    if output:
        print(output)
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
